/**
 * `browser.highlight` as configuration (docs/specs/SPEC-interaction-highlight.md
 * §7, §10.1 case 1): what the loader accepts and refuses, that the generated
 * schema agrees with it, how `resolveHighlight` normalises, that the server
 * path takes the PROJECT's value (§7.3, the trap `resolveRunSettings` warns
 * about), and the `--highlight` / `--no-highlight` flags.
 *
 * Shaped after tests/video-config.test.ts. The schema file is a committed
 * artifact regenerated by `npm run build:schema` (part of `npm run build`).
 */
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import Ajv from 'ajv';
import { Command } from 'commander';
import { applyCliOverrides, loadConfig } from '../src/config/loader.js';
import { resolveRunSettings } from '../src/config/run-settings.js';
import { DEFAULT_CONFIG } from '../src/config/defaults.js';
import type { Config } from '../src/config/types.js';
import { HIGHLIGHT_DEFAULTS, reportAudience, resolveHighlight, ringsOutOfScreenshots } from '../src/browser/highlight.js';
import { registerRunCommand } from '../src/cli/commands/run.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

describe('browser.highlight — the loader', () => {
  let tmpDir: string;
  // The loader layers the machine's user-root .env under the project; point
  // the user root at this test's own empty folder so nothing on the
  // developer's machine can reach the config under test (CLAUDE.md, "Don't
  // read the developer's machine").
  const savedUserRoot = {
    LOCALAPPDATA: process.env['LOCALAPPDATA'],
    XDG_CONFIG_HOME: process.env['XDG_CONFIG_HOME'],
  };

  beforeEach(async () => {
    tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'steptix-highlight-'));
    process.env['LOCALAPPDATA'] = tmpDir;
    process.env['XDG_CONFIG_HOME'] = tmpDir;
  });

  afterEach(async () => {
    for (const [key, value] of Object.entries(savedUserRoot)) {
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
    await fs.rm(tmpDir, { recursive: true, force: true, maxRetries: 3 });
  });

  async function writeConfig(obj: unknown): Promise<string> {
    const file = path.join(tmpDir, 'steptix.config.json');
    await fs.writeFile(file, JSON.stringify(obj), 'utf8');
    return file;
  }

  it('defaults to false when unspecified', async () => {
    // A folder with no config file: the loader would otherwise read the cwd's.
    const config = await loadConfig(undefined, tmpDir);
    expect(config.browser.highlight).toBe(false);
  });

  it('passes true, false and the object form through, keeping sibling defaults', async () => {
    expect((await loadConfig(await writeConfig({ browser: { highlight: true } }))).browser.highlight).toBe(true);
    expect((await loadConfig(await writeConfig({ browser: { highlight: false } }))).browser.highlight).toBe(false);
    const object = { enabled: true, durationMs: 5000, colors: { act: '#123', read: '#00aaff' }, inScreenshots: false };
    const config = await loadConfig(await writeConfig({ browser: { highlight: object } }));
    expect(config.browser.highlight).toEqual(object);
    expect(config.browser.headed).toBe(true);
  });

  it.each([
    ['the string "true"', 'true', /Invalid browser\.highlight in .*steptix\.config\.json: expected true, false or an object, got the string "true"/],
    ['a number', 1, /Invalid browser\.highlight in .*: expected true, false or an object, got the number 1/],
    ['a quoted enabled', { enabled: 'false' }, /Invalid browser\.highlight\.enabled in .*: expected true or false, got the string "false"/],
    ['a quoted inScreenshots', { inScreenshots: 'false' }, /Invalid browser\.highlight\.inScreenshots in .*: expected true or false, got the string "false"/],
    ['a duration below 500', { durationMs: 50 }, /Invalid browser\.highlight\.durationMs in .*: expected a number of milliseconds from 500 to 10000, got the number 50/],
    ['a duration above 10000', { durationMs: 10_001 }, /durationMs .*got the number 10001/],
    ['a named colour', { colors: { act: 'blue' } }, /Invalid browser\.highlight\.colors\.act in .*: expected a hex colour such as "#3b82f6", got the string "blue"/],
    ['an unknown colour key', { colors: { click: '#fff' } }, /Invalid browser\.highlight\.colors in .*: expected only act, read, got "click"/],
    ['an unknown key', { duration: 3000 }, /Invalid browser\.highlight in .*: expected only enabled, durationMs, colors, inScreenshots, got "duration"/],
  ])('refuses %s', async (_name, value, message) => {
    const file = await writeConfig({ browser: { highlight: value } });
    await expect(loadConfig(file)).rejects.toThrow(message);
  });
});

describe('steptix.config.schema.json — browser.highlight agrees with the loader', () => {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  let validate: any;

  beforeEach(async () => {
    const schemaText = await fs.readFile(path.resolve(__dirname, '../schema/steptix.config.schema.json'), 'utf8');
    validate = new Ajv({ strict: false, allErrors: true }).compile(JSON.parse(schemaText));
  });

  it.each([
    [true],
    [false],
    [{ enabled: true }],
    [{ enabled: false, durationMs: 500 }],
    [{ inScreenshots: false }],
    [{ durationMs: 10_000, colors: { act: '#3b82f6', read: '#ABC' } }],
  ])('accepts %j', (value) => {
    expect(validate({ browser: { highlight: value } })).toBe(true);
  });

  it.each([
    ['true'],
    [1],
    [{ enabled: 'false' }],
    [{ inScreenshots: 'false' }],
    [{ durationMs: 50 }],
    [{ durationMs: 10_001 }],
    [{ colors: { act: 'blue' } }],
    [{ colors: { click: '#fff' } }],
    [{ duration: 3000 }],
  ])('rejects %j', (value) => {
    expect(validate({ browser: { highlight: value } })).toBe(false);
  });
});

describe('resolveHighlight', () => {
  it('is null for off, absent, and an object switched off', () => {
    expect(resolveHighlight({ highlight: false })).toBeNull();
    expect(resolveHighlight({ highlight: undefined })).toBeNull();
    expect(resolveHighlight(undefined)).toBeNull();
    expect(resolveHighlight({ highlight: { enabled: false, durationMs: 5000 } })).toBeNull();
  });

  it('gives true every default', () => {
    expect(resolveHighlight({ highlight: true })).toEqual(HIGHLIGHT_DEFAULTS);
    expect(HIGHLIGHT_DEFAULTS).toEqual({ durationMs: 3000, colors: { act: '#3b82f6', read: '#a855f7' }, inScreenshots: true });
  });

  it('reads a written object as on, and fills in what it leaves out', () => {
    expect(resolveHighlight({ highlight: { durationMs: 5000 } })).toEqual({
      durationMs: 5000,
      colors: HIGHLIGHT_DEFAULTS.colors,
      inScreenshots: true,
    });
    expect(resolveHighlight({ highlight: { enabled: true, colors: { read: '#0af' } } })).toEqual({
      durationMs: 3000,
      colors: { act: '#3b82f6', read: '#0af' },
      inScreenshots: true,
    });
    expect(resolveHighlight({ highlight: { inScreenshots: false } })?.inScreenshots).toBe(false);
  });

  it('ringsOutOfScreenshots keeps the rings but out of every report capture, and leaves off as off', () => {
    const on = ringsOutOfScreenshots({ highlight: { durationMs: 4000 }, headed: true });
    expect(on.headed).toBe(true);
    expect(resolveHighlight(on)).toEqual({ durationMs: 4000, colors: HIGHLIGHT_DEFAULTS.colors, inScreenshots: false });
    // Off still records the audience, so a run that draws nothing keeps a
    // ring someone else drew out of its pictures (review round 1, finding 6).
    const off = ringsOutOfScreenshots({ highlight: false });
    expect(off.highlight).toEqual({ enabled: false, inScreenshots: false });
    expect(resolveHighlight(off)).toBeNull();
    expect(reportAudience(off)).toBe('model');
    expect(reportAudience({ highlight: false })).toBe('report');
    expect(reportAudience({ highlight: true })).toBe('report');
    expect(reportAudience({ highlight: { inScreenshots: false } })).toBe('model');
  });

  it('never hands a caller the shared defaults object', () => {
    const resolved = resolveHighlight({ highlight: true })!;
    resolved.colors.act = '#000';
    expect(HIGHLIGHT_DEFAULTS.colors.act).toBe('#3b82f6');
  });
});

describe('resolveRunSettings — browser.highlight is the project\'s', () => {
  // The executor's `browser` slice is spread from the SERVER's startup config,
  // so a key that is not re-sourced by name keeps the server's answer whatever
  // the project says. Both directions, as for `ambiguousTarget`: a resolver
  // that echoed the server config would pass a one-way check.
  const server: Config = { ...DEFAULT_CONFIG, browser: { ...DEFAULT_CONFIG.browser, highlight: false } };
  const withHighlight = (value: Config['browser']['highlight']): Config => ({
    ...server,
    browser: { ...server.browser, highlight: value },
  });

  it("carries the PROJECT's highlight into the config handed to the executor", () => {
    const project = withHighlight({ enabled: true, durationMs: 4000 });
    const { config } = resolveRunSettings(server, project, server.ai.model, {});
    expect(config.browser.highlight).toEqual({ enabled: true, durationMs: 4000 });
  });

  it('does not let a server that highlights impose it on a silent project', () => {
    const highlightingServer = withHighlight(true);
    const { config } = resolveRunSettings(highlightingServer, server, server.ai.model, {});
    expect(config.browser.highlight).toBe(false);
  });
});

describe('--highlight / --no-highlight', () => {
  /** A `steptix` program with only `run` on it, whose action records its options. */
  function program(): { cli: Command; action: ReturnType<typeof vi.fn> } {
    const cli = new Command();
    registerRunCommand(cli);
    const run = cli.commands.find((c) => c.name() === 'run')!;
    const action = vi.fn();
    run.action(action);
    for (const c of [cli, run]) c.exitOverride().configureOutput({ writeErr: () => {}, writeOut: () => {} });
    return { cli, action };
  }

  it.each([
    [[], undefined],
    [['--highlight'], true],
    [['--no-highlight'], false],
  ])('%j parses to highlight %j', async (flags, expected) => {
    const { cli, action } = program();
    await cli.parseAsync(['run', ...flags], { from: 'user' });
    expect(action).toHaveBeenCalledTimes(1);
    expect((action.mock.calls[0]![1] as { highlight?: boolean }).highlight).toBe(expected);
  });

  const base = (value: Config['browser']['highlight']): Config => ({
    ...DEFAULT_CONFIG,
    browser: { ...DEFAULT_CONFIG.browser, highlight: value },
  });

  it('switches the object form off and keeps its duration and colours', () => {
    const project = base({ enabled: true, durationMs: 6000, colors: { act: '#123456' } });
    expect(applyCliOverrides(project, { highlight: false }).browser.highlight).toEqual({
      enabled: false,
      durationMs: 6000,
      colors: { act: '#123456' },
    });
    expect(resolveHighlight(applyCliOverrides(project, { highlight: false }).browser)).toBeNull();
  });

  it('switches a project that is off on, and keeps its settings', () => {
    expect(applyCliOverrides(base(false), { highlight: true }).browser.highlight).toBe(true);
    const off = base({ enabled: false, durationMs: 1000 });
    expect(resolveHighlight(applyCliOverrides(off, { highlight: true }).browser)).toEqual({
      durationMs: 1000,
      colors: HIGHLIGHT_DEFAULTS.colors,
      inScreenshots: true,
    });
  });

  it('leaves the project alone without a flag', () => {
    const project = base({ enabled: true });
    expect(applyCliOverrides(project, {}).browser.highlight).toEqual({ enabled: true });
  });
});
